import json
n=30
g=[[0]*n for _ in range(n)]
tiles=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Recreate the visible tiled input, including the clipped fifth row/column border.
starts=range(1,30,7)
for ti,r0 in enumerate(starts):
 for tj,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     if dr in (0,4) or dc in (0,4): g[r][c]=4
     elif ti<4 and tj<4: g[r][c]=tiles[ti][tj]
# Extend rare-color regions horizontally and vertically between aligned occurrences.
# Color 3: rows 0,2 across tile cols 0..3; cols 0,3 across tile rows 0..2.
# Color 8: rows 1,3 across tile cols 1..2; cols 1,2 across tile rows 1..3.
for tr, color, cfirst, clast in [(0,3,0,3),(2,3,0,3),(1,8,1,2),(3,8,1,2)]:
 r0=1+7*tr
 for dr in (1,2,3):
  for tc in range(cfirst,clast):
   for c in range(1+7*tc+5,1+7*(tc+1)):
    if g[r0+dr][c]==0: g[r0+dr][c]=color
for tc,color,rfirst,rlast in [(0,3,0,2),(3,3,0,2),(1,8,1,3),(2,8,1,3)]:
 c0=1+7*tc
 for dc in (1,2,3):
  for tr in range(rfirst,rlast):
   for r in range(1+7*tr+5,1+7*(tr+1)):
    if g[r][c0+dc]==0: g[r][c0+dc]=color
print(json.dumps(g,separators=(',',':')))
